const nasional = tr.beban_puncak_nasional.baris;
const sis = Object.fromEntries(tr.sistem.map((s) => [s.id, s]));
const ba = (iso) => ase.baris.find((b) => b.iso3 === iso);
const vre = (iso) => { const b = ba(iso).bauran_listrik_persen; return Math.round(((b.surya?.nilai || 0) + (b.angin?.nilai || 0)) * 100) / 100; };
const bp24 = nasional.find((b) => b.tahun === 2024).beban_puncak_mw;
